<?php
session_start();if(($_SESSION['role']??'')!=='admin'||empty($_SESSION['user_id'])){header('Location: /authenication/login/login.php');exit;}require_once(__DIR__.'/../../../Database/db/db.php');$pdo=get_db();$q=$pdo->prepare('SELECT email,ip_address,success,attempt_time FROM login_attempts WHERE user_id=? OR email=(SELECT email FROM users WHERE id=?) ORDER BY attempt_time DESC LIMIT 30');$q->execute([(int)$_SESSION['user_id'],(int)$_SESSION['user_id']]);$attempts=$q->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Security activity';include(__DIR__.'/../../includes/header/header.php');include(__DIR__.'/../../includes/navbar/navbar.php');include(__DIR__.'/../../includes/sidebar/sidebar.php');
?>
<main class="main-content"><div class="container-fluid"><div class="page-heading"><div><span class="page-kicker">ACCOUNT SECURITY</span><h1>Security activity</h1><p>Review recent sign-in attempts recorded for your account.</p></div></div><div class="row g-3 mb-4"><div class="col-sm-6"><div class="metric-card"><span class="metric-icon green"><i class="fa-solid fa-lock"></i></span><span class="metric-label">Current account</span><strong><?=htmlspecialchars($_SESSION['username'],ENT_QUOTES,'UTF-8')?></strong><small>Administrator access</small></div></div><div class="col-sm-6"><div class="metric-card"><span class="metric-icon blue"><i class="fa-solid fa-clock-rotate-left"></i></span><span class="metric-label">Recent records</span><strong><?=count($attempts)?></strong><small>Up to 30 sign-in attempts</small></div></div></div><section class="card border-0"><div class="table-toolbar"><div><h2 class="h5 mb-1">Recent sign-in attempts</h2><p class="text-muted small mb-0">A successful attempt is marked as allowed.</p></div></div><div class="table-responsive"><table class="table admin-table mb-0" data-admin-sort><thead><tr><th data-sort>Email</th><th data-sort>IP address</th><th data-sort>Result</th><th data-sort>Time</th></tr></thead><tbody><?php if(!$attempts):?><tr><td colspan="4"><div class="empty-state"><i class="fa-solid fa-shield-halved"></i><strong>No sign-in records found</strong><span>Login activity will appear here when recorded by the authentication flow.</span></div></td></tr><?php endif;?><?php foreach($attempts as $attempt):?><tr><td><?=htmlspecialchars($attempt['email']??'',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($attempt['ip_address']??'Unknown',ENT_QUOTES,'UTF-8')?></td><td><span class="status-pill <?=$attempt['success']?'status-active':'status-inactive'?>"><i></i><?=$attempt['success']?'Allowed':'Denied'?></span></td><td><?=htmlspecialchars(date('M j, Y g:i A',strtotime($attempt['attempt_time'])),ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php include(__DIR__.'/../../includes/footer/footer.php');?>


